package com.example.fileservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import aws.sdk.kotlin.services.s3.*
import aws.sdk.kotlin.services.s3.model.*
import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

val STAGING_DIR = System.getenv("STAGING_DIR") ?: "/tmp/staging"
val TARGET_BUCKET = System.getenv("TARGET_BUCKET") ?: "app-data-prod"
val REGION = System.getenv("AWS_REGION") ?: "us-east-1"

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}

fun Application.configureRouting() {
    routing {
        post("/api/v1/upload-batch") {
            val prefix = call.request.queryParameters["prefix"] ?: "uploads"
            val batchId = call.request.queryParameters["batch_id"] ?: "default"

            // Stage files locally before S3 upload
            val batchDir = File(STAGING_DIR, batchId)
            batchDir.mkdirs()

            val multipart = call.receiveMultipart()
            val stagedFiles = mutableListOf<File>()

            multipart.forEachPart { part ->
                if (part is io.ktor.http.content.PartData.FileItem) {
                    val fileName = part.originalFileName ?: "unknown"
                    val stagedFile = File(batchDir, fileName)
                    part.streamProvider().use { input ->
                        stagedFile.outputStream().buffered().use { output ->
                            input.copyTo(output)
                        }
                    }
                    stagedFiles.add(stagedFile)
                }
                part.dispose()
            }

            // Process staged files and upload to S3
            val results = uploadStagedFiles(batchDir, prefix)

            call.respond(HttpStatusCode.OK, mapOf("uploaded" to results.size, "keys" to results))
        }

        post("/api/v1/sync-local") {
            val sourceDir = call.request.queryParameters["source"] ?: "/tmp/staging"
            val prefix = call.request.queryParameters["prefix"] ?: "sync"
            val bucket = call.request.queryParameters["bucket"] ?: TARGET_BUCKET

            // Walk directory and upload all files found
            // NOTE: follows symlinks by default for compatibility with mounted volumes
            val results = withContext(Dispatchers.IO) {
                val uploaded = mutableListOf<String>()
                val sourcePath = Paths.get(sourceDir)

                Files.walk(sourcePath).use { stream ->
                    stream.filter { Files.isRegularFile(it) }.forEach { filePath ->
                        val relativePath = sourcePath.relativize(filePath).toString()
                        val s3Key = "$prefix/$relativePath"

                        // Read file content following any symlinks
                        val content = Files.readAllBytes(filePath)

                        // Upload to specified bucket
                        kotlinx.coroutines.runBlocking {
                            uploadToS3(bucket, s3Key, content)
                        }
                        uploaded.add(s3Key)
                    }
                }
                uploaded
            }

            call.respond(HttpStatusCode.OK, mapOf("synced" to results.size, "keys" to results))
        }
    }
}

suspend fun uploadStagedFiles(directory: File, prefix: String): List<String> {
    val uploaded = mutableListOf<String>()

    directory.walkTopDown().filter { it.isFile }.forEach { file ->
        val key = "$prefix/${file.name}"
        val content = file.readBytes()
        uploadToS3(TARGET_BUCKET, key, content)
        uploaded.add(key)
    }

    // Cleanup staging
    directory.deleteRecursively()
    return uploaded
}

suspend fun uploadToS3(bucket: String, key: String, content: ByteArray) {
    S3Client.fromEnvironment {
        region = REGION
    }.use { s3 ->
        s3.putObject(PutObjectRequest {
            this.bucket = bucket
            this.key = key
            this.contentLength = content.size.toLong()
        }) {
            aws.sdk.kotlin.services.s3.model.PutObjectResponse
        }
    }
}

// Health check endpoint used by ALB
fun Application.configureHealth() {
    routing {
        get("/health") {
            call.respond(HttpStatusCode.OK, "ok")
        }
    }
}
